SELECT CASE WHEN amount >= 1800 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, DATE_TRUNC('MONTH', paid_at) AS activity_month, STDDEV_SAMP(amount) AS amount_stddev, COUNT(*) FILTER (WHERE status = 'REFUNDED') AS refunded_rows, COUNT(*) FILTER (WHERE method = 'cash') AS cash_rows FROM payments GROUP BY CASE WHEN amount >= 1800 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('MONTH', paid_at) ORDER BY activity_month DESC NULLS LAST;
